const anchor = "| [[海外赚钱路子（Reddit真实案例）]] | app 矩阵 14 个收订阅月入 $1K、actorle 月入 $4K、12 个 AI 副业实测、beermoney 年入 $30k、UX 测试 $20-50/天、Reddit RSS 抓法 | 10-16 |";
const add = anchor + "\n| [[海外独立开发者方法论（无聊工具五步法）]] | **最可操作的一份**：搜 hours per week 找抱怨 → 查竞品 → $25-50/月 → 一周做出最简单版本 → 发回原 sub。附三个真实抱怨案例 | 10-16 |";
await tools.edit({ file_path: B + "目录.md", old_string: anchor, new_string: add });
const msg = "新增海外独立开发者方法论（无聊工具五步法）：核心认知是$5K/月=100-200人付$25-50；五步法（Reddit搜hours per week找真实抱怨→要2-3个评价平平的竞品→查现价→一周做最简版→发回原sub）；三个真实抱怨案例（物业追租$29/月、记账拉对账单$19/月、婚礼策划看板$39/月）；micro saas 12位创始人调研；擦窗工网站案例；避坑（AI内容代理已饱和、第一个月不可能赚钱）；海外站可抓性实测表；GitHub bounty仓库集中度（3个仓库占87/98）；目录.md 同步为 15 篇";
const cmd = "git -C " + JSON.stringify(B) + " add -A && git -C " + JSON.stringify(B) + " commit -m " + JSON.stringify(msg) + " && git -C " + JSON.stringify(B) + " push";
const r = await tools.pwsh({ command: cmd, description: "Commit and push methodology note", timeoutMs: 180000 });
console.log(r.kind === "foreground" ? (r.stdout.text + r.stderr.text).slice(0, 2200) : JSON.stringify(r).slice(0, 2000));
